mapper.select:
SELECT id, principal_issuer, principal_subject_id, principal_type, agent_id,
       agent_version, scope_kind, workspace_id, resource_type, resource_id, valid_from,
       valid_until, status, version
FROM ainer_authorization_acting_grant
WHERE principal_issuer = #{issuer}
  AND principal_subject_id = #{subjectId}
  AND status = 'ACTIVE'
  AND valid_from <= #{at}
  AND (valid_until IS NULL OR valid_until > #{at})
ORDER BY created_at, id
